import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { CreateHost } from '../host.ts';

const create: CreateHost = createHost;

test('submit validates maxTries and duplicate ids', async () => {
  const h = await create();
  for (const n of [0, 4, -1, 1.5, NaN]) assert.equal((await h.submit('x', n)).ok, false);
  assert.equal(await h.job('x'), null);
  assert.deepEqual(await h.submit('a', 2), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
  assert.equal((await h.submit('a', 1)).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('unknown job ids are refused', async () => {
  const h = await create();
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) {
    const r = await h[c]('nope');
    assert.equal(r.ok, false);
    if (!r.ok) assert.equal(typeof r.reason, 'string');
  }
});

test('retries up to the limit, then fails', async () => {
  const h = await create();
  await h.submit('a', 2);
  assert.equal((await h.claim('a')).ok, true);
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.fail('a')).ok, true);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, true);
  assert.equal((await h.lost('a')).ok, true);
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) assert.equal((await h[c]('a')).ok, false);
});

test('succeed', async () => {
  const h = await create();
  await h.submit('a', 1);
  assert.equal((await h.succeed('a')).ok, false);
  await h.claim('a');
  assert.equal((await h.succeed('a')).ok, true);
  assert.deepEqual(await h.job('a'), { status: 'succeeded', tries: 1, maxTries: 1 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel queued and running', async () => {
  const h = await create();
  await h.submit('q', 3);
  assert.equal((await h.cancel('q')).ok, true);
  assert.deepEqual(await h.job('q'), { status: 'cancelled', tries: 0, maxTries: 3 });

  await h.submit('r', 1);
  await h.claim('r');
  assert.equal((await h.cancel('r')).ok, true);
  assert.equal((await h.job('r'))?.status, 'cancelling');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.claim('r')).ok, false);
  assert.equal((await h.succeed('r')).ok, true);
  assert.equal((await h.job('r'))?.status, 'succeeded');

  await h.submit('s', 3);
  await h.claim('s');
  await h.cancel('s');
  assert.equal((await h.lost('s')).ok, true);
  assert.deepEqual(await h.job('s'), { status: 'cancelled', tries: 1, maxTries: 3 });
});

test('fresh systems are independent', async () => {
  const a = await create();
  await a.submit('j', 1);
  const b = await create();
  assert.equal(await b.job('j'), null);
});

