'use strict';

// SAM v2 strict-profile spec of one job (src/jobs.ts + src/host.impl.ts).
// Jobs are independent, so one job id covers the stateful core.
// status 'none' means no job with this id has been submitted.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', tries: 0, maxTries: 0 };

const bare = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const failAcceptor = (model) => (proposal, { reject, next, unchanged }) => {
  if (model.status === 'cancelling') {
    next.status = 'cancelled';
    return unchanged('tries', 'maxTries');
  }
  if (model.status !== 'running') return reject('fail-needs-running-or-cancelling');
  next.status = model.tries < model.maxTries ? 'queued' : 'failed';
  unchanged('tries', 'maxTries');
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      tries: { type: 'number' },
      maxTries: { type: 'number' },
    },
    actions: {
      SUBMIT: {
        action: (data = {}) => ({ ...data }),
        schema: { maxTries: { type: 'number' } },
        domain: [{ maxTries: 0 }, { maxTries: 1 }, { maxTries: 2 }, { maxTries: 3 }, { maxTries: 4 }, { maxTries: 1.5 }],
      },
      CLAIM: bare(),
      SUCCEED: bare(),
      FAIL: bare(),
      LOST: bare(),
      CANCEL: bare(),
      HOLD: bare(),
      RELEASE: bare(),
    },
    acceptors: {
      SUBMIT: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('job-exists');
        const n = proposal.maxTries;
        if (!Number.isInteger(n) || n < 1 || n > 3) return reject('maxTries-out-of-range');
        next.status = 'queued';
        next.tries = 0;
        next.maxTries = n;
      },
      CLAIM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'queued') return reject('claim-needs-queued');
        if (model.tries >= model.maxTries) return reject('no-tries-left');
        next.status = 'running';
        next.tries = model.tries + 1;
        unchanged('maxTries');
      },
      SUCCEED: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'running' && model.status !== 'cancelling') return reject('succeed-needs-running-or-cancelling');
        next.status = 'succeeded';
        unchanged('tries', 'maxTries');
      },
      FAIL: failAcceptor,
      LOST: failAcceptor,
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'queued' || model.status === 'held') {
          next.status = 'cancelled';
          return unchanged('tries', 'maxTries');
        }
        if (model.status === 'running') {
