  none: { action: 'SUBMIT', data: { maxTries: 1 } },
  queued: { action: 'CANCEL', data: {} },
  running: { action: 'SUCCEED', data: {} },
  cancelling: { action: 'FAIL', data: {} },
};
await explore([]);
console.log(`wrote ${files} trace files`);

