      if (!result.ok) return { ok: false, reason: result.reason };
      jobs.set(id, result.job);
      return { ok: true };
    },
    async claim(id) { return apply(id, core.claim); },
    async succeed(id) { return apply(id, core.succeed); },
    async fail(id) { return apply(id, core.fail); },
