// Captures real execution traces of src/host.impl.ts for polygraph replay:
// every command sequence up to DEPTH on one job id, one NDJSON window per step.
// Run: node spec/capture.ts
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const DEPTH = 6;
const ID = 'j';
type Cmd = { action: string; data: Record<string, number> };
const CMDS: Cmd[] = [
  ...[0, 1, 2, 3, 4, 1.5].map((n) => ({ action: 'SUBMIT', data: { maxTries: n } })),
  ...['CLAIM', 'SUCCEED', 'FAIL', 'LOST', 'CANCEL', 'HOLD', 'RELEASE'].map((action) => ({ action, data: {} })),
];

type Host = Awaited<ReturnType<typeof createHost>>;
const observe = async (h: Host) => (await h.job(ID)) ?? { status: 'none', tries: 0, maxTries: 0 };
const run = (h: Host, c: Cmd) => {
  switch (c.action) {
    case 'SUBMIT': return h.submit(ID, c.data.maxTries);
    case 'CLAIM': return h.claim(ID);
    case 'SUCCEED': return h.succeed(ID);
    case 'FAIL': return h.fail(ID);
    case 'LOST': return h.lost(ID);
    case 'HOLD': return h.hold(ID);
    case 'RELEASE': return h.release(ID);
    default: return h.cancel(ID);
  }
};

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

// Enumerate sequences, pruning ones that only repeat refusals (they add no new state).
let files = 0;
const seen = new Set<string>();
async function explore(prefix: Cmd[]): Promise<void> {
  const h = await createHost();
  const lines: string[] = [];
  const step = async (c: Cmd) => {
    const pre = await observe(h);
    await run(h, c);
    const post = await observe(h);
    lines.push(JSON.stringify({ pre, action: c.action, data: c.data, post }));
    return { pre, post };
  };
  let last: { pre: object; post: { status: string } } | null = null;
  for (const c of prefix) last = await step(c);
  if (last) {
    const c = prefix[prefix.length - 1];
    const key = JSON.stringify([last.pre, c.action, c.data]);
    if (seen.has(key) && JSON.stringify(last.pre) === JSON.stringify(last.post)) return;
    seen.add(key);
  }
  const status = last ? last.post.status : 'none';
  if (prefix.length < DEPTH && !TERMINAL.includes(status)) {
    for (const c of CMDS) await explore([...prefix, c]);
  }
  if (!last) return;
  // Close the scenario in a terminal state, so every trace is a complete run.
  for (let s = status; !TERMINAL.includes(s); s = (await step(CLOSE[s])).post.status);
  writeFileSync(new URL(`t${String(files++).padStart(5, '0')}.ndjson`, dir), lines.join('\n') + '\n');
}
