// Builds the negative-control mutants from spec/jobs.spec.cjs. Run: node spec/controls/make.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const src = readFileSync(new URL('../jobs.spec.cjs', import.meta.url), 'utf8');
const mutants = {
  // A cancelling job whose try failed ends failed, losing the cancel.
  'mutant-cancelling-fail': [
    "next.status = 'cancelled';\n    return unchanged('tries', 'maxTries');\n  }\n  if (model.status !== 'running')",
    "next.status = 'failed';\n    return unchanged('tries', 'maxTries');\n  }\n  if (model.status !== 'running')",
  ],
  // A worker can claim a held job.
  'mutant-claim-held': [
    "if (model.status !== 'queued') return reject('claim-needs-queued');",
    "if (model.status !== 'queued' && model.status !== 'held') return reject('claim-needs-queued');",
  ],
  // A retryable failure fails the job early, as if permanent.
  'mutant-fail-early': [
    "next.status = model.tries < model.maxTries ? 'queued' : 'failed';",
    "next.status = 'failed';",
  ],
  // A resubmitted job keeps the tries it already used.
  'mutant-resubmit-keeps-tries': [
    "next.status = 'queued';\n        next.tries = 0;",
    "next.status = 'queued';\n        next.tries = model.tries;",
  ],
};
for (const [name, [from, to]] of Object.entries(mutants)) {
  const out = src.replace(from, to);
  if (out === src) throw new Error(`${name}: pattern not found`);
  writeFileSync(new URL(`./${name}.cjs`, import.meta.url), out);
}
console.log(`wrote ${Object.keys(mutants).length} mutants`);

